const defaults=[['给自己买一束花','reward','❀'],['晒15分钟太阳','goal','☼'],['记录今天的心情','record','☷'],['吃一顿想吃的饭','reward','♨'],['拍一张喜欢的天空','record','☁'],['独自逛一次书店','reward','▤'],['写下喜欢自己的3个地方','record','♡'],['睡一个不用闹钟的觉','reward','☾'],['尝试一项新爱好','goal','✧'],['认真听完一张专辑','reward','♫'],['拒绝一次不想做的事','goal','⤴'],['给自己准备一份礼物','reward','♧'],['今天不必完成任何事','free','♡'],['去一个没去过的地方','goal','⌁'],['记录一件开心的小事','record','✎'],['看一部想看的电影','reward','▷'],['给未来的自己写封信','record','✉'],['尝试一道新菜','goal','♨'],['拍下今天最喜欢的瞬间','record','▧'],['和喜欢的人见面','reward','❋'],['散一次没有目的地的步','goal','⌇'],['做一次身体放松','reward','〰'],['记录最近的小小进步','record','↗'],['安排一次独处约会','goal','✶'],['为一件小事庆祝','reward','✷']];
const key='little-care-bingo-v1';let cards=defaults.map(x=>[...x]),marks=[12],filter='all',editing=false;const $=s=>document.querySelector(s),types={record:'记录型',goal:'目标型',reward:'奖励型',free:'给自己的拥抱'};let shared=false;
function valid(s){return s&&Array.isArray(s.cards)&&s.cards.length===25&&s.cards.every((c,i)=>Array.isArray(c)&&c.length===3&&typeof c[0]==='string'&&c[0].length>0&&c[0].length<=40&&c[1]===defaults[i][1]&&c[2]===defaults[i][2])&&Array.isArray(s.marks)&&s.marks.every(n=>Number.isInteger(n)&&n>=0&&n<25)}
try{let s;if(location.hash.startsWith('#card=')){s=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(decodeURIComponent(location.hash.slice(6))),c=>c.charCodeAt(0))));shared=true}else{s=JSON.parse(localStorage.getItem(key))}if(valid(s)){cards=s.cards;marks=[...new Set(s.marks)]}}catch{setTimeout(()=>toast('卡片未能读取，已为你准备一张新的'),400)}
function save(){try{localStorage.setItem(key,JSON.stringify({cards,marks}))}catch{}}function lineCount(){let n=0;for(let r=0;r<5;r++)if(Array.from({length:5},(_,c)=>r*5+c).every(i=>marks.includes(i)))n++;for(let c=0;c<5;c++)if(Array.from({length:5},(_,r)=>r*5+c).every(i=>marks.includes(i)))n++;if([0,6,12,18,24].every(i=>marks.includes(i)))n++;if([4,8,12,16,20].every(i=>marks.includes(i)))n++;return n}
function render(){const grid=$('#grid');grid.replaceChildren();cards.forEach((c,i)=>{const b=document.createElement('button');b.className='cell'+(marks.includes(i)?' done':'')+(c[1]==='free'?' free':'')+(filter!=='all'&&c[1]!==filter?' dim':'');b.dataset.type=c[1];b.setAttribute('aria-pressed',String(marks.includes(i)));b.setAttribute('aria-label',`${c[0]}，${marks.includes(i)?'已点亮':'未点亮'}${editing?'，点击编辑':''}`);for(const [cls,txt] of [['type',types[c[1]]],['symbol',c[2]],['label',c[0]],['number',String(i+1).padStart(2,'0')]]){const span=document.createElement('span');span.className=cls;span.textContent=txt;if(cls!=='label')span.setAttribute('aria-hidden','true');b.append(span)}b.onclick=()=>{if(editing){editCard(i);return}if(filter!=='all'&&c[1]!==filter){toast('这格属于'+types[c[1]]+'，切换「全部」后点亮它');return}let before=lineCount();marks=marks.includes(i)?marks.filter(x=>x!==i):[...marks,i];save();render();if(lineCount()>before){toast('Bingo！给认真爱自己的你，一个小奖励 ♡');$('#grid').classList.remove('bingo-pulse');void $('#grid').offsetWidth;$('#grid').classList.add('bingo-pulse')}};grid.append(b)});$('#progress').textContent=`已点亮 ${marks.length} / 25 格`;$('#lines').textContent=lineCount()?`✧ ${lineCount()} 条 Bingo`:'每一小步都算数';$('#progressBar').style.width=marks.length/25*100+'%';$('#gentle').textContent=marks.length===25?'满格的关爱，也记得把温柔留给明天的自己。':lineCount()?'连线完成啦，记得兑现给自己的小奖励 ♡':'今天不必完成任何事。你本来就值得被好好对待。';$('#edit').textContent=editing?'✓ 完成编辑':'✎ 编辑卡片'}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}function modal(html){$('#modalContent').innerHTML=html;$('#modal').showModal()}$('#close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()});$('#edit').onclick=()=>{editing=!editing;render();if(editing)toast('点击任意一格，写下你自己的关爱清单')};function editCard(i){modal('<h3>这一格，留给自己</h3><p>一件小事就好，不必太用力。</p><label for="cardText">自我关爱小事（最多 40 字）</label><textarea id="cardText" rows="3" maxlength="40"></textarea><button class="primary" id="saveCard">保存这一格 ♡</button>');$('#cardText').value=cards[i][0];$('#saveCard').onclick=()=>{const t=$('#cardText').value.trim();if(!t){toast('写下一件想为自己做的小事吧');return}cards[i][0]=t;save();render();$('#modal').close()}}
$('#reset').onclick=()=>{modal('<h3>开启新一轮关爱？</h3><p>会清除这张卡的点亮记录，保留你编辑的内容。中心格仍会为你点亮。</p><button class="primary" id="confirmReset">好，重新开始</button><button class="secondary" id="cancelReset">再留一会儿</button>');$('#confirmReset').onclick=()=>{marks=[12];save();render();$('#modal').close();toast('新的开始，也请对自己温柔一点')};$('#cancelReset').onclick=()=>$('#modal').close()};$('#help').onclick=()=>modal('<h3>没有输赢，只有关爱。</h3><p>① 选一件今天想为自己做的小事。<br>② 做完后轻点格子，再点一次可以取消。<br>③ 横、竖、斜任意五格连线，就是一次 Bingo。<br>④ 连线后，送给自己一个小奖励吧。</p><p>可以编辑卡片、筛选类型、下载图片，或分享当前卡片与进度。你的打卡会自动保存在这个浏览器；分享后的两张卡各自记录，不会实时同步。</p>');
function shareUrl(){const bytes=new TextEncoder().encode(JSON.stringify({cards,marks}));return location.origin+location.pathname+'#card='+encodeURIComponent(btoa(Array.from(bytes,b=>String.fromCharCode(b)).join('')))}async function copy(t){try{await navigator.clipboard.writeText(t);toast('链接已复制，把这份温柔分享出去吧 ♡')}catch{const input=$('#shareLink');input.focus();input.select();toast('请长按或按 Ctrl/Cmd+C 复制链接')}}$('#share').onclick=()=>{modal('<span class="mini-label">A LITTLE CARE TO SHARE</span><h3 style="margin-top:12px">把温柔，分享给另一个人。</h3><p>链接包含这张卡片的内容和当前进度。朋友打开后，可以拥有自己的打卡记录。</p><label for="shareLink">你的专属卡片链接</label><input id="shareLink" readonly><button id="copy" class="primary">复制分享链接 ↗</button><button id="nativeShare" class="secondary">更多分享方式</button><p style="font-size:11px">也可以下载为图片，发给朋友或打印下来。</p>');$('#shareLink').value=shareUrl();$('#copy').onclick=()=>copy(shareUrl());$('#nativeShare').onclick=async()=>{if(navigator.share){try{await navigator.share({title:'给自己的 25 件小事 · 自我关爱 Bingo',text:'把时间分一点给自己，和我一起慢慢点亮这张卡吧 ♡',url:shareUrl()})}catch(e){if(e.name!=='AbortError')copy(shareUrl())}}else copy(shareUrl())}};
function wrap(ctx,text,max){let rows=[],s='';for(const ch of text){if(ctx.measureText(s+ch).width>max&&s){rows.push(s);s=ch}else s+=ch}if(s)rows.push(s);return rows}function rounded(ctx,x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
$('#download').onclick=async()=>{const btn=$('#download');btn.disabled=true;btn.textContent='正在制作图片…';try{await document.fonts.ready;const c=document.createElement('canvas');c.width=1800;c.height=2220;const ctx=c.getContext('2d');ctx.fillStyle='#faf7ef';ctx.fillRect(0,0,c.width,c.height);ctx.textAlign='center';ctx.fillStyle='#8b9078';ctx.font='22px sans-serif';ctx.fillText('L I T T L E   C A R E   C L U B',900,95);ctx.fillStyle='#514c43';ctx.font='500 78px "Noto Serif SC", serif';ctx.fillText('好好爱自己',900,205);ctx.font='32px "Noto Serif SC", serif';ctx.fillText('也可以是一场小小的游戏。',900,272);ctx.font='23px sans-serif';ctx.fillStyle='#91867c';ctx.fillText('把时间分一点给自己，把普通日子过得柔软一点。',900,332);const colors={record:'#dee7d7',goal:'#dee7f1',reward:'#f0dde2',free:'#e8ddcc'};cards.forEach((card,i)=>{const x=90+i%5*328,y=405+Math.floor(i/5)*314,w=310,h=296,done=marks.includes(i);ctx.fillStyle=done?'#d0d9c3':colors[card[1]];rounded(ctx,x,y,w,h,14);if(done){ctx.strokeStyle='#899477';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#73815e';ctx.font='28px sans-serif';ctx.fillText('✓',x+w-24,y+34)}ctx.fillStyle='#817d71';ctx.font='16px sans-serif';ctx.textAlign='left';ctx.fillText(types[card[1]],x+18,y+30);ctx.textAlign='center';ctx.fillStyle='#74765f';ctx.font='57px serif';ctx.fillText(card[2],x+w/2,y+116);ctx.fillStyle='#514c43';ctx.font='23px "Noto Serif SC", sans-serif';const rows=wrap(ctx,card[0],w-38);rows.forEach((t,j)=>ctx.fillText(t,x+w/2,y+177+j*34));ctx.fillStyle='#9b968a';ctx.font='14px sans-serif';ctx.fillText(String(i+1).padStart(2,'0'),x+w-22,y+h-14)});ctx.fillStyle='#6c775f';ctx.font='25px sans-serif';ctx.fillText(`已点亮 ${marks.length} / 25 格  ·  ${lineCount()} 条 Bingo`,900,2040);ctx.fillStyle='#91867c';ctx.font='26px "Noto Serif SC", serif';ctx.fillText('今天不必完成任何事。你本来就值得被好好对待。',900,2110);ctx.font='17px sans-serif';ctx.fillText('自我关爱 BINGO  ·  每一小步都算数 ♡',900,2166);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw Error('export');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='好好爱自己-Bingo.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('卡片已生成，愿你把温柔带在身边 ♡')}catch{toast('图片生成失败，请再试一次')}finally{btn.disabled=false;btn.textContent='↓ 下载我的卡片'}};
render();if(shared){save();history.replaceState(null,'',location.pathname+location.search);setTimeout(()=>toast('收到一份小小关爱，开始你的专属打卡吧 ♡'),500)}
